2.fn:
            $order->update_meta_data( $meta_key, $number );
            $order->save();
        }
        return $number;
    } finally {
        if ( $got ) $wpdb->query( $wpdb->prepare( 'SELECT RELEASE_LOCK(%s)', $lock ) );
    }
}
