function petshop_get_invoice_document_type( $order ) {
    if ( ! $order instanceof WC_Order ) return 'invoice';
    // S1795 (2026-10-23, Raimio sprendimas): įmonei/įstaigai, kuri moka pavedimu tik pagal PVM s/f, sąskaita išrašoma prieš apmokėjimą.
    // Žyma _ps_pvm_sf_neapmoketa=1 dedama rankiniu būdu (bridge), data fiksuojama _petshop_sf_data.
    if ( (string) $order->get_meta( '_ps_pvm_sf_neapmoketa' ) === '1' ) {
        return 'invoice';
    }
    // S1662 (Raimio taisyklė 2026-09-09): PVM sąskaita (AVPN) — TIK apmokėtiems.
    // Kol neapmokėta (bet kuris mokėjimo būdas) — išankstinė (IAPV).
    // Anksčiau proforma buvo tik bacs pending/on-hold — Paysera pending degino AVPN numerius.
    if ( $order->is_paid() ) {
        return 'invoice';
    }
    if ( in_array( $order->get_status(), array( 'pending', 'on-hold', 'failed', 'checkout-draft' ), true ) ) {
        return 'proforma';
    }
    // cancelled/refunded be apmokėjimo — sąskaitos nekuriam, bet jei kas pareikalaus, NEdeginam AVPN
    if ( in_array( $order->get_status(), array( 'cancelled', 'refunded' ), true ) && ! $order->get_date_paid() ) {
        return 'proforma';
    }
    return 'invoice';
}

function petshop_get_invoice_title( $order ) {
    $type     = petshop_get_invoice_document_type( $order );
    $order_id = $order->get_id();
    if ( $type === 'proforma' ) {
        return array(
            'title'  => 'Išankstinisė sąskaita',
            'number' => petshop_get_iapv_number( $order_id ),
        );
    }
    return array(
        'title'  => 'PVM sąskaita faktūra',
        'number' => petshop_get_avpn_number( $order_id ),
    );
}

